const STOP = new Set(["a","au","aux","avec","ce","ces","cette","de","des","du","dans","et","est","en","je","la","le","les","ma","mes","mon","ne","nous","on","ou","pour","que","quel","quelle","quels","quelles","qui","quoi","se","son","sur","ta","te","tes","ton","tu","un","une","vos","votre","comment","pourquoi","faire","sert","signifie","veut","dire","fonctionne","explique","expliquer","moi","application","appli","awena"]);
function norm(value: string) { return String(value || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[’']/g, " ").replace(/[_/\\.-]+/g, " ").replace(/[^a-z0-9+%\s]/g, " ").replace(/\s+/g, " ").trim(); }
function tokens(value: string) { return norm(value).split(" ").filter((t) => t.length > 1 && !STOP.has(t)); }

