function rememberedId(topic?: string) { return String(topic || "").startsWith("masterv89:") ? String(topic).slice(10) : ""; }
function score(entry: MasterV89Entry, q: string, rememberedTopic?: string) {
  let s = rememberedId(rememberedTopic) === entry.id ? 10 : 0; const qt = new Set(tokens(q));
  for (const raw of [entry.title, ...entry.aliases]) { const a = norm(raw); if (!a) continue; if (q === a) s += 46; else if (a.length >= 4 && q.includes(a)) s += 19; const at = tokens(a); let m = 0; for (const t of at) if (qt.has(t)) { m++; s += t.length >= 6 ? 3.6 : 2.1; } if (at.length >= 2 && m === at.length) s += 8; }
  return s;
}
function render(entry: MasterV89Entry, q: string) {
  const problem = /marche pas|fonctionne pas|erreur|probleme|problème|bloque|bloqué|bug|diagnostic/.test(q);
  const how = /comment|utiliser|configurer|mettre en place|faire pour|en pratique/.test(q);
  const deep = /detail|détail|technique|expert|precis|précis|approfond|complet|complexe|pourquoi/.test(q);
  let out = `## ${entry.title.toUpperCase()}\n${entry.simple}`;
  if (deep || (!how && !problem && q.length > 52)) out += `\n\n## POUR ALLER PLUS LOIN\n${entry.deep}`;
  if (how || deep) out += `\n\n## EN PRATIQUE\n${entry.practical}`;
  if (problem || deep) out += `\n\n## DIAGNOSTIC / VIGILANCE\n${entry.diagnostic}`;
  if (!deep && !how && !problem) out += `\n\n**À retenir :** ${entry.practical}`;
  return out;
}
export function answerAwenaMasterKnowledgeV89(question: string, context: AwenaRuntimeContext, rememberedTopic?: string): AwenaReply | null {
  const q = norm(question); if (!q) return null; const rid = rememberedId(rememberedTopic);
  const follow = /^(?:plus de details|plus de détails|approfondis|explique davantage|pourquoi|comment|et en pratique|ca ne marche pas|ça ne marche pas|diagnostic)$/i.test(String(question || "").trim());
  if (follow && rid) { const e = ENTRIES.find((x) => x.id === rid); if (e) return { text: render(e, `${q} detail`), knowledgeTopic: `masterv89:${e.id}`, modeId: context.mode || null }; }
  let best: { entry: MasterV89Entry; score: number } | null = null; for (const entry of ENTRIES) { const s = score(entry, q, rememberedTopic); if (!best || s > best.score) best = { entry, score: s }; }
  if (!best || best.score < 14) return null; return { text: render(best.entry, q), knowledgeTopic: `masterv89:${best.entry.id}`, modeId: context.mode || null };
}
export function awenaMasterKnowledgeV89Count() { return ENTRIES.length; }
export function awenaMasterKnowledgeV89AliasCount() { return ENTRIES.reduce((sum, e) => sum + e.aliases.length, 0); }
export function awenaMasterKnowledgeV89DomainCount() { return new Set(ENTRIES.map((e) => e.domain)).size; }
